// Generated by `npm run chat:probe -- --from-trace` (T-0174) from 2026-10-16.jsonl:944,2026-10-16.jsonl:945,2026-10-16.jsonl:946 (catalog agent-ui--concierge).
// Keyless: the recorded model rounds replay through the real produce(), then the probe checks run with
// no browser. The browser leg is `npm run chat:probe -- --replay concierge-haiku-orphan-update.json` from this folder.
import { readFileSync } from 'node:fs'
import { expect, it } from 'vitest'
import { parseProbeFixture } from '../model.ts'
import { offlineReplay } from '../trace.ts'

// expectedFail: round 7 cluster B (T-0303, 2026-10-16-r7-fails :4-:6, Haiku 5.5). Round 1 created ask-1 and got
// BOOKING_FORM_MISSING at ask-1:summary; round 2 sent the BookingForm as updates to ask-1 with no createSurface. The
// failure named ask-1, so no SURFACE_DROPPED fired, the validator accepted updates to a surface never created, and
// the guest never saw the form. Pinned to today's behavior; a fix flips no-surface-loss:0.
const trace = (record) => record.lines.map((l) => JSON.parse(l)).map((l) => l.a2uiMeta?.trace).find((t) => t !== undefined)

it('concierge-haiku-orphan-update: a repair round that updates ask-1 without creating it ships, and the form is lost', async () => {
  const fixture = parseProbeFixture(readFileSync(new URL('./concierge-haiku-orphan-update.json', import.meta.url), 'utf8'))
  const report = await offlineReplay(fixture, process.cwd())
  expect(report.failed.map((c) => `${c.check}:${c.turn}`)).toEqual(['no-surface-loss:0'])
  const booking = report.records[0]
  expect(trace(booking)).toMatchObject({ rounds: 2, failureCodes: ['BOOKING_FORM_MISSING'] })
  const wire = booking.lines.map((l) => JSON.parse(l))
  expect(wire.some((m) => m.createSurface !== undefined)).toBe(false)
  expect(wire.some((m) => m.updateComponents?.surfaceId === 'ask-1')).toBe(true)
})
